// wifi_nvs.h - multi-network WiFi with credentials kept in NVS (ESP32, Arduino core).
// Generated by the esp32-wifi-provisioning skill. Needs include/wifi_secrets.h (gitignored).
//
// Usage:
//   #include "wifi_nvs.h"
//   void setup() { Serial.begin(115200); wifinvs::begin(); }
//   void loop()  { wifinvs::loop(); /* your code */ }
#pragma once
#include <Arduino.h>

#ifndef WIFI_NVS_MAX
#define WIFI_NVS_MAX 8          // max networks kept in NVS
#endif

#ifndef WIFI_NVS_SERIAL_CMDS
#define WIFI_NVS_SERIAL_CMDS 1  // loop() answers "#wifi-list" on Serial (lines starting with '#' only)
#endif

namespace wifinvs {
// Sync built-in networks into NVS (only when they changed), scan, join the strongest
// known one. If none works, open the setup portal (AP "ESP32-Setup-XXXX", http://192.168.4.1).
bool begin(uint32_t connectTimeoutMs = 10000);
// Call often from loop(): serves the portal, reconnects after a long drop-out.
void loop();
bool isConnected();
bool isPortalActive();
// Add or update one network in NVS (also used by the portal).
bool addNetwork(const char* ssid, const char* pass);
// Erase every network stored in NVS (built-in ones come back on next boot).
void clearAll();
// For apps that read Serial themselves (set WIFI_NVS_SERIAL_CMDS 0): pass each received line.
// "#wifi-list" prints the stored networks for pull-wifi-from-board.ps1. Returns true if handled.
bool handleSerialLine(const String& line);
}  // namespace wifinvs
